'use strict';

// File-backed session store for express-session (audit fix M4).
//
// Replaces the default MemoryStore, which express-session itself warns is
// unsuitable for production: it leaks memory (expired sessions are only
// evicted lazily and never under load patterns with many unique visitors)
// and dies with the process, logging everyone out on every restart.
//
// Design:
// - One JSON file per session under session/sessions/, keyed by session ID.
// - Session IDs are generated by express-session's uid (URL-safe chars), but
//   the filename is validated against a strict regex anyway so no
//   crafted cookie can ever escape the directory.
// - Expired sessions are removed on read and swept periodically, so disk and
//   memory stay bounded even under bot traffic.
// - Writes are debounced per session (coalesces the dashboard's frequent
//   req.session.touch-style writes), and writes never crash the app: a
//   failed write surfaces as a store error, express-session handles it.
//
// Single-process only (same constraint as the JSON DB in lib/db.js). For
// multi-instance deployments use Redis or a real shared store.

const fs = require('fs');
const path = require('path');
const { Store } = require('express-session');

class FileSessionStore extends Store {
    /**
     * @param {object} opts
     * @param {string} opts.dir          Directory to store session files in.
     * @param {number} [opts.ttl]        Session TTL in ms (default 24h). Should
     *                                   match the cookie maxAge in autoviewer.js.
     * @param {number} [opts.sweepMs]    Sweep interval in ms (default 10min).
     */
    constructor(opts) {
        super();
        this.dir = opts.dir;
        this.ttl = opts.ttl || 24 * 60 * 60 * 1000;
        this.sweepMs = opts.sweepMs || 10 * 60 * 1000;
        this.log = opts.log || ((...a) => console.warn('[SessionStore]', ...a));

        fs.mkdirSync(this.dir, { recursive: true });

        // Deferred queue: session ID -> timer. Coalesces rapid writes.
        this._pending = new Map();
        this._cache = new Map(); // session ID -> parsed session (hot reads)
        this._cacheTtl = 60 * 1000;
        this._writes = new Map(); // session ID -> tail of the per-session write chain
        this._destroyed = new Set(); // session IDs whose unlink is still queued
        this._tmpSeq = 0;
        this._closed = false;

        this._sweepTimer = setInterval(() => this._sweep(), this.sweepMs);
        this._sweepTimer.unref();

        this._sweep(); // clear out sessions left by a previous run
    }

    _file(sessionId) {
        if (!/^[A-Za-z0-9,_-]{8,}$/.test(sessionId)) {
            throw new Error('invalid session id');
        }
        return path.join(this.dir, sessionId + '.json');
    }

    _expiry(sessJson, ttlOverride) {
        const ttl = ttlOverride || this.ttl;
        const cookie = sessJson && sessJson.cookie;
        // express-session passes the store's own expiry in the cookie's
        // `expires` field when the cookie has a maxAge; prefer that.
        if (cookie && cookie.expires) {
            const t = Date.parse(cookie.expires);
            if (!Number.isNaN(t)) return t;
        }
        return Date.now() + ttl;
    }

    get(sessionId, callback) {
        // A destroy() whose unlink is still queued must not be undone by a
        // concurrent read of the not-yet-deleted file.
        if (this._destroyed.has(sessionId)) {
            return process.nextTick(() => callback(null, null));
        }
        const cached = this._cache.get(sessionId);
        if (cached && cached.expires > Date.now()) {
            return process.nextTick(() => callback(null, cached.sess));
        }
        this._cache.delete(sessionId);
        let raw;
        try { raw = fs.readFileSync(this._file(sessionId), 'utf8'); }
        catch (err) {
            if (err.code === 'ENOENT') return process.nextTick(() => callback(null, null));
            return process.nextTick(() => callback(err));
        }
        let entry;
        try { entry = JSON.parse(raw); }
        catch (_) { return process.nextTick(() => callback(null, null)); }
        if (!entry || entry.expires <= Date.now()) {
            return process.nextTick(() => callback(null, null));
        }
        this._cache.set(sessionId, { sess: entry.sess, expires: entry.expires, at: Date.now() });
        return process.nextTick(() => callback(null, entry.sess));
    }

    set(sessionId, sess, callback) {
        try { this._file(sessionId); }
        catch (err) {
            if (callback) process.nextTick(() => callback(err));
            return;
        }
        this._destroyed.delete(sessionId);
        // Read-your-writes: express-session may finish the response — and the
        // client may issue its NEXT request — before this debounced write
        // lands. res.sendFile() streams the body and completes without waiting
        // for our callback (the old res.send(html) held the last byte until
        // the write finished, which is why this never showed up before), so a
        // GET followed immediately by a POST could read a session file that
        // does not exist yet, get handed a brand-new session, and fail every
        // CSRF check. Publishing the new state to the cache synchronously
        // closes that window. The payload is cloned: it is exactly what will
        // be serialized to disk, and it must not alias the live session
        // object express-session is still holding.
        this._cache.set(sessionId, {
            sess: JSON.parse(JSON.stringify(sess)),
            expires: this._expiry(sess),
            at: Date.now()
        });
        // Coalesce writes: the dashboard polls and rewrites CSRF/session data
        // frequently; only the last write within the debounce window matters.
        // Every superseded caller's callback is kept and answered with the
        // result of the coalesced write — dropping them left express-session
        // waiting on a callback that never fired.
        const existing = this._pending.get(sessionId);
        if (existing) clearTimeout(existing.timer);
        const callbacks = existing ? existing.callbacks : [];
        if (callback) callbacks.push(callback);
        const timer = setTimeout(() => {
            this._pending.delete(sessionId);
            this._write(sessionId, sess, (err) => {
                if (err) this.log('write failed:', err.message);
                for (const cb of callbacks) {
                    try { cb(err); } catch (e) { this.log('callback failed:', e.message); }
                }
            });
        }, 50);
        timer.unref?.();
        this._pending.set(sessionId, { timer, sess, callbacks });
    }

    // Serialize writes per session: a slower, older write must never rename
    // its payload over a newer one, and destroy()'s unlink must run after any
    // in-flight write instead of racing it.
    _enqueue(sessionId, work) {
        const prev = this._writes.get(sessionId) || Promise.resolve();
        const next = prev.catch(() => {}).then(work);
        this._writes.set(sessionId, next);
        const cleanup = () => { if (this._writes.get(sessionId) === next) this._writes.delete(sessionId); };
        next.then(cleanup, cleanup);
        return next;
    }

    _write(sessionId, sess, callback) {
        let file;
        try { file = this._file(sessionId); } catch (err) { return callback(err); }
        const expires = this._expiry(sess);
        const payload = JSON.stringify({ expires, sess });
        // Unique temp name: concurrent writes for the same session must never
        // share a temp file, or their contents interleave before the rename.
        const tmp = file + '.tmp-' + process.pid + '-' + (++this._tmpSeq);
        this._enqueue(sessionId, () => new Promise((resolve, reject) => {
            fs.mkdir(this.dir, { recursive: true }, (mkdirErr) => {
                if (mkdirErr) return reject(mkdirErr);
                fs.writeFile(tmp, payload, (writeErr) => {
                    if (writeErr) { fs.unlink(tmp, () => {}); return reject(writeErr); }
                    fs.rename(tmp, file, (renameErr) => {
                        if (renameErr) { fs.unlink(tmp, () => {}); return reject(renameErr); }
                        // A destroy() may have run while this write was in
                        // flight; re-caching here would resurrect the session
                        // after its unlink completes.
                        if (!this._destroyed.has(sessionId)) {
                            this._cache.set(sessionId, { sess, expires, at: Date.now() });
                        }
                        resolve();
                    });
                });
            });
        })).then(() => callback(null), (err) => callback(err));
    }

    /**
     * List the session ids currently on disk (used by the session manager so
     * an account can see and revoke its other logins).
     */
    ids() {
        try {
            return fs.readdirSync(this.dir)
                .filter(f => f.endsWith('.json'))
                .map(f => f.slice(0, -5));
        } catch {
            return [];
        }
    }

    /** Read one session's payload without going through express-session. */
    read(sessionId) {
        try {
            const raw = fs.readFileSync(this._file(sessionId), 'utf8');
            const entry = JSON.parse(raw);
            if (!entry || entry.expires <= Date.now()) return null;
            return entry.sess || null;
        } catch {
            return null;
        }
    }

    /** Destroy several sessions at once (log out everywhere). */
    destroyMany(sessionIds, callback) {
        const ids = Array.isArray(sessionIds) ? sessionIds.filter(Boolean) : [];
        if (!ids.length) return callback && callback(null, 0);
        let done = 0;
        let lastErr = null;
        for (const id of ids) {
            this.destroy(id, (err) => {
                if (err) lastErr = err;
                if (++done === ids.length) callback && callback(lastErr, done);
            });
        }
    }

    destroy(sessionId, callback) {
        const pending = this._pending.get(sessionId);
        if (pending) {
            clearTimeout(pending.timer);
            this._pending.delete(sessionId);
            // The debounced write will never run — answer its callers now so
            // express-session can finish the request that queued them.
            for (const cb of pending.callbacks) {
                try { cb(null); } catch (e) { this.log('callback failed:', e.message); }
            }
        }
        this._cache.delete(sessionId);
        this._destroyed.add(sessionId);
        let file;
        try { file = this._file(sessionId); }
        catch (err) {
            this._destroyed.delete(sessionId);
            return callback && callback(err);
        }
        this._enqueue(sessionId, () => new Promise((resolve, reject) => {
            fs.unlink(file, (err) => {
                if (err && err.code !== 'ENOENT') reject(err);
                else resolve();
            });
        })).then(
            () => {
                // The in-flight write path skips caching once _destroyed is
                // set, but an entry cached just before destroy() must also go.
                this._cache.delete(sessionId);
                this._destroyed.delete(sessionId);
                if (callback) callback(null);
            },
            (err) => {
                this._cache.delete(sessionId);
                this._destroyed.delete(sessionId);
                if (callback) callback(err);
            }
        );
    }

    // express-session calls touch() on every request whose data did not change
    // but whose cookie still has a maxAge. Answering that without writing left
    // the stored `expires` frozen at creation + ttl, so an active user was
    // logged out exactly 24h after signing in (their browser cookie was still
    // valid, the session file no longer was). Route it through the same
    // debounced writer as set() so the stored expiry slides with the cookie.
    touch(sessionId, sess, callback) {
        return this.set(sessionId, sess, callback);
    }

    _sweep() {
        if (this._closed) return;
        let files;
        try { files = fs.readdirSync(this.dir); } catch (_) { return; }
        const now = Date.now();
        for (const name of files) {
            const file = path.join(this.dir, name);
            if (name.includes('.tmp-')) {
                // Leftover temp file from a crashed write — clean it up once it
                // is clearly stale (an in-flight write finishes in milliseconds).
                try {
                    if (now - fs.statSync(file).mtimeMs > 60 * 60 * 1000) fs.unlinkSync(file);
                } catch (_) { /* raced with the writer/another sweep */ }
                continue;
            }
            if (!name.endsWith('.json')) continue;
            try {
                const entry = JSON.parse(fs.readFileSync(file, 'utf8'));
                if (entry && entry.expires < now) fs.unlinkSync(file);
            } catch (_) { /* unreadable/corrupt: skip, sweep again next round */ }
        }
        // Evict stale cache entries so hot-reads don't pin old expiry data.
        for (const [id, entry] of this._cache) {
            if (entry.expires < now || now - entry.at > this._cacheTtl) this._cache.delete(id);
        }
    }

    close() {
        this._closed = true;
        clearInterval(this._sweepTimer);
        for (const [, p] of this._pending) {
            clearTimeout(p.timer);
            // Don't strand express-session requests waiting on a callback.
            for (const cb of p.callbacks) {
                try { cb(new Error('session store closed')); } catch (e) { /* ignore */ }
            }
        }
        this._pending.clear();
        this._cache.clear();
    }
}

module.exports = { FileSessionStore };
